Matching Ayahs
- = Alif, Lam, Meem. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Awo ali pa njira yowongoka yochokera kwa Mbuye wawo, ndipo ndi awo amene apambana. 2:5; 31:5
- = Oh ana a Israeli, kumbukirani chisomo Changa chimene ndinakupatsani ndi kuti ndinakusankhani kuposa mitundu yonse (ya anthu). 2:47; 2:122
- = Umenewo unali mtundu umene unapita. Zomwe unapeza nzake, ndipo zomwe inu mwapeza ndi zanu. Ndipo simudzafunsidwa za zomwe iwo ankachita. 2:134; 2:141
- = Kukhala momwemo mpaka kalekale. Chilango sichidzachepetsedwa kwa iwo, ndipo sadzapatsidwa nthawi yopumula. 2:162; 3:88
- = Kupatula amene alapa pambuyo pake ndi kudzikonza. Ndithudi, Allah ndi Wokhululuka, Wachifundo Chambiri. 3:89; 24:5
- = Ndipo amene sakhulupirira ndi kukana zizindikiro Zathu – iwo ndi eni ake a Moto. 5:10; 5:86
- = Ndipo palibe chizindikiro chochokera kwa Mbuye wawo chimene chimawadzera, koma iwo amachitembenukira. 6:4; 36:46
- = Ndipo atumwi ananyozedwa kale iwe usanadze, koma amene ankawanyoza anazunguliridwa ndi zimene ankazinyoza. 6:10; 21:41
- = Nena: "Ndithudi ine ndikuopa, ngati nditanyoza Mbuye wanga, chilango cha Tsiku Lalikulu." 6:15; 39:13
- = Chivomezi chinawagwera, ndipo anakhala m'nyumba mwawo atagona chafufumimba. 7:78; 7:91
- = Ndipo iye anaponya ndodo yake, ndipo taonani, inakhala njoka yowonekera. 7:107; 26:32
- = Ndipo anatulutsa dzanja lake, ndipo taonani, linali loyera (lowala) kwa onlooka. 7:108; 26:33
- = Iwo anati: "Takhulupirira Mbuye wa zolengedwa zonse." 7:121; 26:47
- = Mbuye wa Mose ndi Aroni. 7:122; 26:48
- = Ndipo ndiwapatsa nthawi. Ndithudi, chiwembu changa ndi cholimba. 7:183; 68:45
- = Iye ndi amene anatumiza Mtumiki wake ndi chiongoko ndi chipembedzo choonadi, kuti achioneketse pamwamba pa zipembedzo zonse, ngakhale opembedza mafano akunyansa. 9:33; 61:9
- = Oh Mneneri, menyana ndi osakhulupirira ndi onyenga, ndipo khala wokhwima kwa iwo. Ndipo malo awo ndi Gahena, ndipo kuipa kwa malo obwererawo! 9:73; 66:9
