- Allah, Yemwe ali ndi zonse zimene zili m'thambo ndi zimene zili m'nthaka. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- Pakati pa mibado yomwe inalipo inu musanadze, kuchokera ku majini ndi anthu. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- Pembedzani Allah, mulibe mulungu wina kusiyapo Iye, kodi simukuopa? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- Ndipo Ife tidaika zophimba pa mitima yawo kuti asazimvetse, ndipo m'makutu mwawo kunalepheretsa. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- Iye adzaweruza pakati pawo pa Tsiku la Chimaliziro pa zomwe iwo amakangana. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- Iye adati: "Ee anthu anga! Mukuona bwanji ngati ine ndili pa umboni wowonekera wochokera kwa Mbuye wanga?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- Ichi ndi chifukwa cha zomwe manja anu adatsogoza, ndipo Allah si wozunza akapolo Ake. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- Iwo ali ndi manyazi m'dziko lapansi ndipo ali ndi chilango chachikulu ku Mbuyo. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- Zimene zili m'thambo ndi zimene zili m'nthaka, ndipo Allah akukwanira kukhala Msungi. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- Kupatula amene adakhulupirira ndi kuchita ntchito zabwino; iwo ali ndi mphotho yosatha. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- Kuti undiphatikize Ine ndi zomwe ulibe chidziwitso; choncho usawamvere iwo. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- Ndithudi ichi ndi chikumbutso; ndipo amene afuna, atenge njira yopita kwa Mbuye wake. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- Ndipo amene akuthokoza, akuthokoza chifukwa cha moyo wake; ndipo amene akukana. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- Amene amaima mapemphero ndi kupereka msonkho waulele, ndipo iwo amakhulupirira Mbuyo. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- Kwa Ibrahim, Ishmael, Isaac, Yakub ndi mafuko, ndi zomwe zidaperekedwa kwa Musa ndi Yesu. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- M'magulu, mpaka pamene iwo afika kumeneko, zitseko zake zidzatsegulidwa, ndipo alonda ake adzati kwa iwo. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- Allah sadzakulangani chifukwa cha mawu opanda pake m'malumbiro anu, koma Iye adzakulangani chifukwa cha. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- Chifundo, iwo amasangalala nacho, ndipo ngati mavuto awagwera chifukwa cha zomwe manja awo adatsogoza. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- Minda yamaluwa yomwe mitsinje ikuyenda pansi pake, iwo adzakhala momwemo nthawi zonse, ndipo mphotho ya ogwira ntchito ndi yabwino bwanji! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- Allah amadziwa zimene zili m'thambo ndi zimene zili m'nthaka, ndipo Allah. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- Mverani Allah ndi kumvera Mtumiki; ngati mutembenuka, ndiye kuti udindo wake ndi. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- Iwo ali ndi mphotho yawo kwa Mbuye wawo, ndipo palibe mantha pa iwo, ndipo iwo. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- Ndipo iwo adati: "Kodi pamene ife tikhala mafupa ndi fumbi, kodi ife tidzaukitsidwa kukhala cholengedwa chatsopano?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- Ndipo iwo sadzapeza wina kusiyapo Allah amene angawathandize kapena kuwapulumutsa. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "Kodi unakhala nthawi yaitali bwanji?" Iye adati: "Ndakhala tsiku limodzi kapena gawo la tsiku." Iye adati. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- Mpakana Tsiku la Chimaliziro, ndani mulungu wina kusiyapo Allah amene angakubweretsereni? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- Amene achita zabwino, wamwamuna kapena wamkazi, ndipo iye ndi wokhulupirira. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- Amene amaletsa anthu ku njira ya Allah ndipo amafuna kuti ikhale yopotoka, ndipo iwo pa Mbuyo. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- Idyani kumene mwafuna, koma musayandikire mtengo uwu, kuti musakhale olakwa. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- Nena: "Ee anthu anga! Chitani monga momwe mwalili, ine ndikuchita, ndipo posachedwa mudzadziwa." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- Ndithudi otayika ndi amene adzataya miyoyo yawo ndi mabanja awo pa Tsiku la Chimaliziro, kodi si. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- Amene atsogozedwa, atsogozedwa chifukwa cha moyo wake; ndipo amene asochera, asochera chifukwa cha moyo wake, ndipo. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- Ndipo amene sakhulupirira amati: "Bwanji chizindikiro sichinavumbulutsidwe kwa iye kuchokera kwa Mbuye wake?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- Amene adakupangirani usiku kuti mupumule mmenemo ndi usana kuti muone, ndithudi. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- Lisanafike tsiku limene mulibe malonda ndipo mulibe. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- Kuti aganize kuti mzangawo alibe misala; iye si kanthu koma mchenjezi. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- Iwo adzakhala momwemo nthawi zonse, chilango sichidzachepetsedwa kwa iwo, ndipo sadzapatsidwa nthawi. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- Usatambasule maso ako ku zomwe Ife tawapatsa ena a iwo kuti akondwere. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- Ndipo musawachepetsere anthu zinthu zawo, ndipo musachite zachiwembu m'nthaka. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- Ndipo mtendere ukhale pa iye pa tsiku limene adabadwa, ndi pa tsiku limene adzafa, ndi pa tsiku limene adzaukitsidwa kukhala wamoyo. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- Ee anthu anga! Chitani monga momwe mwalili, ine ndikuchita, ndipo posachedwa mudzadziwa kuti ndani. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- Ndipo sikunali kwa Mtumiki kuti abweretse chizindikiro pokhapokha ndi chilolezo cha Allah. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- Kenako moyo uliwonse udzalandira mphotho yake mokwanira pa zomwe unachita, ndipo iwo sadzaponderezedwa. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- Wamwamuna kapena wamkazi, ndipo iye ndi wokhulupirira, ndiye iwo adzalowa m'Paradaiso. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- Iye sanatenge mwana, ndipo analibe mnzake mu ufumu. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- Ndipo amene Allah wamutsogolera, ndiye wotsogozedwa; ndipo amene wamusochera, sudzampeza. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- Ona mmene akupatsirani zitsanzo, ndipo asochera, ndipo sangathe kupeza njira. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- Nena: "Ine ndikuopa chilango cha Tsiku Lalikulu ngati ndipandukira Mbuye wanga." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- Maliseche awo adawonekera kwa iwo, ndipo adayamba kudziphimba ndi masamba a m'munda wa paradaiso. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- Ndipo pemphani amene mungathe kuwapempha kusiyapo Allah, ngati ndinu oona. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- Zonse zimene zili m'nthaka ndi zofanana nazo kuti adziwombole nazo. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- Tengani zomwe takupatsani mwamphamvu, ndipo kumbukirani zimene zili mmenemo, kuti mukhale oopa Allah. (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- Kodi mukuchita chinthu chonyansa chomwe palibe amene adachichita inu musanadze m'dziko lonse? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- Ndipo zonse zimene zili m'thambo ndi m'nthaka ndi za Allah, ndipo Allah anali. (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- Zoipa zomwe adachita zidawafikira, ndipo zomwe adanyoza zidawazungulira. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- Mtumiki wochokera mwa inu amene akuwerengera inu mavesi Athu ndi kukuyeretsani ndi kukuphunzitsani Buku ndi nzeru. (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- Mmenemo munatuluka akasupe khumi ndi awiri; gulu lililonse linkadziwa malo ake akumwa. (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- Kupatula kungoganiza; ndithudi kuganiza sikuthandiza chilichonse kutsutsana ndi choonadi. (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- Choncho ndikamaliza kumulenga ndi kuuzira mzimu Wanga mmenemo, gwadani pansi mukumupembedza. (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- Ndani amene adzakhale ndi malo abwino m'dziko lapansi? Ndithudi olakwa sadzapambana. (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- Amene adalenga thambo ndi nthaka ali wokhoza kulenga zofanana ndi iwo. (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- Kwa okhulupirira amuna ndi okhulupirira akazi, minda yamaluwa yomwe mitsinje ikuyenda pansi pake, iwo adzakhala momwemo nthawi zonse. (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
- Ndipo ngati uwafunsa kuti ndani adalenga thambo ndi nthaka, iwo adzati: "Allah." Nena. (وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ) 31:25; 39:38
